def moore_bound(d, g):
    if g % 2 == 1:
        k = (g - 1) // 2
        return sum((d - 1)**i for i in range(k)) * d + 1
    else:
        k = g // 2
        return 2 * sum((d - 1)**i for i in range(k))

print(f"Moore bound for d=3, g=8: {moore_bound(3, 8)}")
print(f"Moore bound for d=4, g=8: {moore_bound(4, 8)}")

def check_moore(n, d_min, g):
    if g % 2 == 1:
        k = (g - 1) // 2
        bound = sum((d_min - 1)**i for i in range(k)) * d_min + 1
    else:
        k = g // 2
        bound = 2 * sum((d_min - 1)**i for i in range(k))
    return n >= bound

print(f"Check for n=19, d_min=4, g=8: {check_moore(19, 4, 8)}")
